{"snapshot_sha256": "8cf0a003ab54e39d292cfc9371f6c7a54fc308ad981218fef0d305da82ad3d05", "policy_sha256": "547f68a1689ca4058022adb9c1c7a6792826ed097dc5f974b284ea39903ba2be", "replacements": [{"path": "runner.py", "before_sha256": "4ad730068bd1e0ef7262240efd01e7b30a2eac6bfd6a62026fa3b134c7601039", "after_utf8": "def total_cents(rows):
    seen = {}
    for invoice, amount in rows:
        if type(amount) is not int or amount < 0:
            raise ValueError("invalid amount")
        if invoice in seen and seen[invoice] != amount:
            raise ValueError("conflicting duplicate")
        seen[invoice] = amount
    return sum(seen.values())
